#!/usr/bin/env node
"use strict";

// Generates apps/web/public-bundle.js — every public/ file as a base64 blob
// inside one CommonJS module. Desktop executables are built with
// `bun build --compile`, which bundles JS modules but does NOT embed loose
// files: __dirname in a compiled binary points at the build machine's source
// path, so file-system reads of public/ work on the build machine and in CI
// (both have the source checked out) but fail on user machines with 404/500.
// This module — required by server.js and therefore bundled — is the only
// source of truth for static assets in desktop builds. Dev runs keep using
// the file system because the file does not exist in a plain checkout
// (gitignored).

const fs = require("node:fs");
const path = require("node:path");

const webDir = path.resolve(__dirname, "..", "apps", "web");
const publicDir = path.join(webDir, "public");
const outFile = path.join(webDir, "public-bundle.js");

const files = {};
function walk(dir, prefix) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, rel);
    } else {
      files[rel] = fs.readFileSync(full).toString("base64");
    }
  }
}
walk(publicDir, "");

const lines = [
  "// GENERATED by scripts/build-public-bundle.js — do not edit.",
  '"use strict";',
  "module.exports = { files: {",
  ...Object.keys(files)
    .sort()
    .map((name) => `  ${JSON.stringify(name)}: Buffer.from(${JSON.stringify(files[name])}, "base64"),`),
  "} };",
  "",
];
fs.writeFileSync(outFile, lines.join("\n"));
console.log(`wrote ${outFile} (${Object.keys(files).length} files)`);
